--
-- Name: exec_cypher(text, text); Type: FUNCTION; Schema: ag_catalog; Owner: -
--

CREATE FUNCTION ag_catalog.exec_cypher(graph_name text, query text) RETURNS SETOF ag_catalog.agtype
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY EXECUTE format(
        'SELECT * FROM cypher(%L, %L) AS (r agtype)',
        graph_name, query
    );
END;
$$;


